head.b:skin:
:root {
  --bg: #0b1020;
  --bg-soft: #131b2d;
  --card: #121a2b;
  --card-2: #182338;
  --text: #edf2ff;
  --muted: #a6b4d3;
  --accent: #7c9dff;
  --accent-2: #5eead4;
  --border: rgba(166,180,211,0.18);
}

body {
  margin: 0;
  background:
    radial-gradient(circle at top left, rgba(124,157,255,0.18), transparent 30%),
    radial-gradient(circle at bottom right, rgba(94,234,212,0.12), transparent 28%),
    var(--bg);
  color: var(--text);
  font-family: 'Segoe UI', Arial, sans-serif;
  line-height: 1.7;
}

* { box-sizing: border-box; }
a { color: var(--accent); text-decoration: none; }
a:hover { color: var(--accent-2); }

.container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(11,16,32,0.8);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
}

.brand {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.nav {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
}

.nav a {
  color: var(--muted);
  font-size: 0.9rem;
}

.hero {
  padding: 72px 0 38px;
}

.hero-inner {
  background: linear-gradient(135deg, rgba(124,157,255,0.14), rgba(94,234,212,0.08));
  border: 1px solid var(--border);
  border-radius: 28px;
  padding: 54px 32px;
}

.eyebrow {
  color: var(--accent-2);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.8rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.hero h1 {
  margin: 0;
  font-size: clamp(2.3rem, 4vw, 4.1rem);
  line-height: 1.08;
}

.hero p {
  max-width: 720px;
  color: var(--muted);
  font-size: 1.07rem;
  margin-top: 18px;
}

.main-grid {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(240px, 0.8fr);
  gap: 28px;
  padding: 20px 0 50px;
}

.posts {
  display: grid;
  gap: 24px;
}

.post-card {
  background: rgba(18,26,43,0.9);
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 26px;
}

.post-card h2 {
  margin: 0 0 10px;
  font-size: clamp(1.5rem, 2vw, 2rem);
}

.meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 16px;
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 18px 0 0;
}

.tag-list span {
  background: rgba(124,157,255,0.12);
  border: 1px solid rgba(124,157,255,0.25);
  color: var(--accent-2);
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 0.72rem;
}

.sidebar {
  display: grid;
  gap: 22px;
}

.panel {
  background: rgba(18,26,43,0.9);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 22px;
}

.panel h3 {
  margin: 0 0 18px;
  font-size: 1rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.panel ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 12px;
}

.panel li {
  color: var(--text);
  border-bottom: 1px solid var(--border);
  padding-bottom: 8px;
}

.panel li:last-child { border-bottom: 0; padding-bottom: 0; }

.footer {
  border-top: 1px solid var(--border);
  padding: 24px 0 40px;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 900px) {
  .main-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .header-inner {
    flex-direction: column;
    justify-content: center;
    padding: 12px 0;
  }

  .nav {
    justify-content: center;
  }

  .hero-inner {
    padding: 34px 18px;
  }
}
